{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Solifenacin, a structurally related antimuscarinic with a basic bicyclic amine and ester/carbamate, has an absolute oral bioavailability of 88% (95% CI 75.8–102.1) in healthy volunteers, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Pethidine, which shares the N-methylpiperidine and ester motif with the query, has mean absolute oral bioavailability of 0.57 ± 0.13 in normal subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Ketanserin, a basic piperidine-containing drug, shows absolute oral bioavailability of 55.5 ± 8.7% in healthy male subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Silodosin, despite extensive first-pass metabolism, has absolute oral bioavailability of 32.2% in healthy men, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Encainide in normal subjects has an absolute oral bioavailability of 32 ± 7%, supporting F ≥ 20% despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Naratriptan, a basic amine drug, has oral bioavailability of 63% in men and 74% in women, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "High: the query is expected to have F ≥ 20%. All high-transfer experimental analogues report mean absolute oral bioavailability between about 30% and 88%, with no affirmative evidence of F < 20%; structural and pharmacological similarity to solifenacin, pethidine, and ketanserin reinforces the prediction.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for propiverine is present in the supplied evidence; prediction relies on close analogues.",
    "Some analogues, such as encainide and sulpiride, show wide interindividual ranges that occasionally fall below 20%, but their mean values remain above the threshold.",
    "No query-specific first-pass metabolism or transporter data are available in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

